{"file_path":"src/lcs.js","content":"/**
 * Longest common subsequence matching between a side (mine or theirs) and the
 * base, with the tie-breaking rule from the specification: when two
 * subsequences are equally long, the one whose matches come earliest wins.
 */

/**
 * Compute the sequence of matched (sideIndex, baseIndex) pairs between
 * `side` and `base`, walking forward and preferring matches, then advancing
 * the side with the strictly larger remaining subsequence, breaking ties by
 * advancing the base.
 */
export function computeMatches(side, base) {
  const n = side.length
  const m = base.length
  // dp[i][j] = length of the LCS of side[i:] and base[j:]
  const dp = []
  for (let i = 0; i <= n; i++) dp.push(new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        const a = dp[i + 1][j]
        const b = dp[i][j + 1]
        dp[i][j] = a > b ? a : b
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const remainingSide = dp[i + 1][j]
      const remainingBase = dp[i][j + 1]
      if (remainingSide > remainingBase) {
        i++
      } else {
        j++
      }
    }
  }
  return matches
}

/**
 * Turn the matched pairs between `side` and `base` into a list of changes.
 * Each change replaces base[start:end] with the given lines from `side`.
 */
export function computeChanges(side, base, matches) {
  const changes = []
  let prevSide = -1
  let prevBase = -1

  const emit = (baseStart, baseEnd, sideStart, sideEnd) => {
    if (baseStart !== baseEnd || sideStart !== sideEnd) {
      changes.push({ start: baseStart, end: baseEnd, lines: side.slice(sideStart, sideEnd) })
    }
  }

  for (const [x, o] of matches) {
    emit(prevBase + 1, o, prevSide + 1, x)
    prevSide = x
    prevBase = o
  }
  emit(prevBase + 1, base.length, prevSide + 1, side.length)

  return changes
}

/** Compute the changes that turn `base` into `side`. */
export function diffAgainstBase(side, base) {
  const matches = computeMatches(side, base)
  return computeChanges(side, base, matches)
}
"}

