/**
 * Group the changes from both sides into merge regions, per the
 * specification: changes are ordered by their base start (mine before
 * theirs on ties), then absorbed into a region while they start at or
 * before the region's current end.
 */
function buildRegionGroups(mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirsChanges.map(c => ({ ...c, side: 'theirs' })),
  ]
  tagged.sort((a, b) => a.start - b.start)

  const groups = []
  let idx = 0
  while (idx < tagged.length) {
    let start = tagged[idx].start
    let end = tagged[idx].end
    const changes = [tagged[idx]]
    idx++
    while (idx < tagged.length && tagged[idx].start <= end) {
      changes.push(tagged[idx])
      if (tagged[idx].end > end) end = tagged[idx].end
      idx++
    }
    groups.push({ start, end, changes })
  }
  return groups
}

/** Reconstruct one side's lines across [start, end) in base coordinates. */
function resolveSide(start, end, changes, base) {
  let pos = start
  const out = []
  for (const change of changes) {
    if (change.start > pos) out.push(...base.slice(pos, change.start))
    out.push(...change.lines)
    pos = change.end
  }
  if (pos < end) out.push(...base.slice(pos, end))
  return out
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Compute the full ordered list of blocks (stable regions and resolved or
 * conflicting merge regions) describing how to turn the base, mine and
 * theirs documents into a merge result.
 */
export function computeBlocks(mine, base, theirs) {
  const mineChanges = diffAgainstBase(mine, base)
  const theirsChanges = diffAgainstBase(theirs, base)
  const groups = buildRegionGroups(mineChanges, theirsChanges)

  const blocks = []
  let pos = 0

  for (const group of groups) {
    if (group.start > pos) {
      blocks.push({ type: 'stable', lines: base.slice(pos, group.start) })
    }

    const mineOwn = group.changes.filter(c => c.side === 'mine')
    const theirsOwn = group.changes.filter(c => c.side === 'theirs')
    const mineLines = resolveSide(group.start, group.end, mineOwn, base)
    const theirsLines = resolveSide(group.start, group.end, theirsOwn, base)
    const baseLines = base.slice(group.start, group.end)

    if (arraysEqual(mineLines, theirsLines)) {
      blocks.push({ type: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      blocks.push({ type: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      blocks.push({ type: 'mine', lines: mineLines })
    } else {
      blocks.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    pos = group.end
  }

  if (pos < base.length) {
    blocks.push({ type: 'stable', lines: base.slice(pos, base.length) })
  }

  return blocks
}
