  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const groups = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      groups.push([])
    } else {
      groups[groups.length - 1].push(line)
    }
  }

  if (groups.length !== 3) return null
  return groups
}
"}

